  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  font-weight: 500;
  color: #646cff;
  text-decoration: inherit;
}
a:hover {
  color: #535bf2;
}

body {
  margin: 0;
  display: flex;
  min-width: 320px;
  min-height: 100vh;
}

h1 {
  font-size: 3.2em;
  line-height: 1.1;
}

button {
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 1em;
  font-weight: 500;
  font-family: inherit;
  background-color: #1a1a1a;
  cursor: pointer;
  transition: border-color 0.25s;
}
button:hover {
  border-color: #646cff;
}
button:focus,
button:focus-visible {
  outline: 4px auto -webkit-focus-ring-color;
}

#app {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
}

@media (prefers-color-scheme: light) {
  :root {
    color: #213547;
    background-color: #ffffff;
  }
  a:hover {
    color: #747bff;
  }
  button {
    background-color: #f9f9f9;
  }
}

/* Existing Vite starter styles */
#center {
  display: grid;
  gap: 32px;
  grid-template-columns: 180px 1fr;
  align-items: center;
  margin-block: 8vh;
}

.hero {
  position: relative;
  width: 180px;
  height: 180px;
}

.hero .base {
  position: absolute;
  inset: 0;
  width: 180px;
  height: 180px;
  object-fit: contain;
}

.hero .framework {
  position: absolute;
  right: -10px;
  bottom: 10px;
  width: 64px;
  height: 64px;
  opacity: 0.9;
}

.hero .vite {
  position: absolute;
  left: -8px;
  top: 12px;
  width: 64px;
  height: 64px;
  opacity: 0.9;
}

.ticks {
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
  margin-block: 32px;
}

#next-steps {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

#docs, #social {
  padding: 20px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 16px;
  text-align: left;
}

#docs .icon, #social .icon {
  width: 28px;
  height: 28px;
  color: rgba(255,255,255,0.7);
}

#docs ul, #social ul {
  list-style: none;
  padding: 0;
  margin: 16px 0 0;
  display: grid;
  gap: 10px;
}

#docs a, #social a {
  display: inline-flex;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(255,255,255,0.05);
}

#docs a:hover, #social a:hover {
  background: rgba(255,255,255,0.08);
}

.logo {
  width: 18px;
  height: 18px;
}

.button-icon {
  width: 18px;
  height: 18px;
}

#spacer {
  height: 20vh;
}

